create table if not exists public.online_class_student_permissions (id bigint generated by default as identity primary key,class_id integer not null references public.online_classes(id) on delete cascade,student_id integer not null references public.students(id) on delete cascade,can_draw boolean not null default false,granted_by uuid,granted_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now(),unique(class_id,student_id));
alter table public.online_class_student_permissions enable row level security;
revoke all on table public.online_class_student_permissions from anon;
grant select,insert,update,delete on table public.online_class_student_permissions to authenticated;
create policy "online class permission teacher read" on public.online_class_student_permissions for select to authenticated using (exists(select 1 from public.online_class_teachers t where t.class_id=online_class_student_permissions.class_id and t.teacher_id=(select private.frahoosh_current_teacher_id())) or student_id=(select private.frahoosh_current_student_id()) or lower(coalesce((select private.frahoosh_current_role()),'')) in ('manager','مدیر','مدیریت','executive','معاون اجرایی'));
create policy "online class permission teacher insert" on public.online_class_student_permissions for insert to authenticated with check (exists(select 1 from public.online_class_teachers t where t.class_id=online_class_student_permissions.class_id and t.teacher_id=(select private.frahoosh_current_teacher_id())) or lower(coalesce((select private.frahoosh_current_role()),'')) in ('manager','مدیر','مدیریت','executive','معاون اجرایی'));
create or replace function public.start_online_class_session(p_class_id integer) returns bigint language plpgsql security definer set search_path='' as $$ declare v_role text:=lower(coalesce((select private.frahoosh_current_role()),''));v_teacher_id integer:=(select private.frahoosh_current_teacher_id());v_session_id bigint;begin if not(v_role in ('manager','مدیر','مدیریت','executive','معاون اجرایی') or exists(select 1 from public.online_class_teachers t where t.class_id=p_class_id and t.teacher_id=v_teacher_id)) then raise exception 'not authorized';end if;insert into public.online_class_sessions(class_id,started_at,created_at) values(p_class_id,now()::text,now()::text) returning id into v_session_id;update public.online_classes set status='active',activated_at=now(),pages=15,smart_board=1,quiz=1,camera=1,microphone=1,record=1 where id=p_class_id;return v_session_id;end;$$;
create or replace function public.record_online_class_checkpoint(p_class_id integer,p_session_id bigint,p_student_id integer,p_checkpoint_no integer) returns text language plpgsql security definer set search_path='' as $$ declare v_current_student integer:=(select private.frahoosh_current_student_id());v_name text;begin if v_current_student is null or v_current_student<>p_student_id then raise exception 'student identity mismatch';end if;if p_checkpoint_no not in(1,2) then raise exception 'invalid checkpoint';end if;if not exists(select 1 from public.online_class_students m where m.class_id=p_class_id and m.student_id=p_student_id) then raise exception 'not class member';end if;if not exists(select 1 from public.online_class_sessions s where s.id=p_session_id and s.class_id=p_class_id and s.ended_at is null) then raise exception 'session inactive';end if;select concat_ws(' ',s.first_name,s.last_name) into v_name from public.students s where s.id=p_student_id;insert into public.online_attendance(class_id,student_id,student_name,status,session_id,source,event_time,recorded_at,checkpoint_no) values(p_class_id,p_student_id,coalesce(v_name,''),case when p_checkpoint_no=2 then 'present_verified' else 'present_pending' end,p_session_id,'standalone_online_class',now()::text,now(),p_checkpoint_no);return case when p_checkpoint_no=2 then 'present_verified' else 'present_pending' end;end;$$;
revoke execute on function public.start_online_class_session(integer) from public,anon;
revoke execute on function public.record_online_class_checkpoint(integer,bigint,integer,integer) from public,anon;
grant execute on function public.start_online_class_session(integer) to authenticated;
grant execute on function public.record_online_class_checkpoint(integer,bigint,integer,integer) to authenticated;